(2918529, 408520, 327, '<td valign="top">Their futures so bright they''ve gotta wear shades. Sorry just made me think of that song. Wow this is some collection and it''s great that you had access to them. I love the composition but the shot is over exposed, not bad but a bit. Your focus is good. Best of luck in the challenge.</td>', 'Their futures so bright they''ve gotta wear shades. Sorry just made me think of that song. Wow this is some collection and it''s great that you had access to them. I love the composition but the shot is over exposed, not bad but a bit. Your focus is good. Best of luck in the challenge.', '2006-10-11 14:15:22.000000', NULL, 1),
(2918531, 409187, 35947, '<td valign="top">Image is pretty grainy, not sure if it was intended or not.  IMHO the grain doesn''t add to this shot.</td>', 'Image is pretty grainy, not sure if it was intended or not.  IMHO the grain doesn''t add to this shot.', '2006-10-11 14:15:37.000000', NULL, 1),
(2918535, 408950, 327, '<td valign="top">really cute composition and really nice light/focus. Well done.</td>', 'really cute composition and really nice light/focus. Well done.', '2006-10-11 14:16:03.000000', NULL, 1),
(2918537, 408481, 35947, '<td valign="top">Image seems grainy/over sharpened maybe.</td>', 'Image seems grainy/over sharpened maybe.', '2006-10-11 14:16:27.000000', NULL, 1),
