(2919484, 407439, 64175, '<td valign="top">This image Does not appear to meet the challenge.<br/> <br/>Details: <b>Include a rubber ducky </b>in your photograph this week.</td>', 'This image Does not appear to meet the challenge. Details: Include a rubber ducky in your photograph this week.', '2006-10-11 17:41:05.000000', NULL, 1),
(2919494, 409361, 64175, '<td valign="top">The ducky is really lost in the photo and there is too much going on.  Very odd photo.  Gunslingers at a wedding in the woods with rubber duckies?</td>', 'The ducky is really lost in the photo and there is too much going on.  Very odd photo.  Gunslingers at a wedding in the woods with rubber duckies?', '2006-10-11 17:42:38.000000', NULL, 1),
(2919496, 408481, 64175, '<td valign="top">There is a lot of noise in the picture.</td>', 'There is a lot of noise in the picture.', '2006-10-11 17:42:49.000000', NULL, 1),
(2919511, 409064, 64175, '<td valign="top">Nice shot. I hate cats, just a subjective pet peeve, so for me to give an 8 on this means you really pulled of a nice shot.<br/> <br/>The pink spots on the rug/towel/carpet beneath the head detreact a bit, but overall it''s a really good shot.  You may want to have cloned out the spots and a bit more of the flash relfection off the ducks face.</td>', 'Nice shot. I hate cats, just a subjective pet peeve, so for me to give an 8 on this means you really pulled of a nice shot. The pink spots on the rug/towel/carpet beneath the head detreact a bit, but overall it''s a really good shot.  You may want to have cloned out the spots and a bit more of the flash relfection off the ducks face.', '2006-10-11 17:45:02.000000', NULL, 1),
(2919516, 409757, 64175, '<td valign="top">I had this at seven but after looking again, it is one of the top 10 entries, so I''m upping it to an 8.</td>', 'I had this at seven but after looking again, it is one of the top 10 entries, so I''m upping it to an 8.', '2006-10-11 17:45:35.000000', NULL, 1),
(2919522, 408832, 64175, '<td valign="top">Ozzy!  Nice. Where do you guys find these Devil Ducks.  Not really the bathtime friend you want for you little one.  Great shot. 7.</td>', 'Ozzy!  Nice. Where do you guys find these Devil Ducks.  Not really the bathtime friend you want for you little one.  Great shot. 7.', '2006-10-11 17:46:36.000000', NULL, 1),
(2919525, 409629, 64175, '<td valign="top">Day trip for a family of quacks. I like it.  Nice pic. 7.</td>', 'Day trip for a family of quacks. I like it.  Nice pic. 7.', '2006-10-11 17:47:05.000000', NULL, 1),
(2919531, 408842, 64175, '<td valign="top">The green relection is great. I don''t really like the cd''s beneath the duck itself as the detrack a bit with the purples, but overall a nice shot. 7.</td>', 'The green relection is great. I don''t really like the cd''s beneath the duck itself as the detrack a bit with the purples, but overall a nice shot. 7.', '2006-10-11 17:47:48.000000', NULL, 1),
(2919533, 408950, 64175, '<td valign="top">Nice Macro shot.</td>', 'Nice Macro shot.', '2006-10-11 17:47:59.000000', NULL, 1),
(2919545, 406848, 64175, '<td valign="top">Nice sharp colors. Grasshopper is really not needed in the shot and the top antenna distracts just a bit as it is over the duck''s face.  8.</td>', 'Nice sharp colors. Grasshopper is really not needed in the shot and the top antenna distracts just a bit as it is over the duck''s face.  8.', '2006-10-11 17:49:40.000000', NULL, 1),
(2919546, 408843, 64175, '<td valign="top">Romantic? I don''t get that part, but Dizzy maybe.  Nice shot. Creative use of light. 7.</td>', 'Romantic? I don''t get that part, but Dizzy maybe.  Nice shot. Creative use of light. 7.', '2006-10-11 17:50:07.000000', NULL, 1),
(2919559, 409587, 64175, '<td valign="top">ha, ha.  Lol.  Nice. I wish the lighting was a littel better on the duck itself. The right (left side of screen) half of the duck is very shadowed. 6.</td>', 'ha, ha.  Lol.  Nice. I wish the lighting was a littel better on the duck itself. The right (left side of screen) half of the duck is very shadowed. 6.', '2006-10-11 17:52:32.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2919560, 409740, 64175, '<td valign="top">Took me a minute to get that they were supposed to be on the lake. Initial reaction was, "what do ducks have to do with a laptop?".   Perhaps a couple of ducks in the screen image would have helped, but then again it may have been too distracting. Great clarity/focus on the shot and nice comp. 6.</td>', 'Took me a minute to get that they were supposed to be on the lake. Initial reaction was, "what do ducks have to do with a laptop?".   Perhaps a couple of ducks in the screen image would have helped, but then again it may have been too distracting. Great clarity/focus on the shot and nice comp. 6.', '2006-10-11 17:52:42.000000', NULL, 1),
(2919562, 408732, 64175, '<td valign="top">Will we see this one in Woody too?  Funny and nice concept.</td>', 'Will we see this one in Woody too?  Funny and nice concept.', '2006-10-11 17:52:49.000000', NULL, 1),
(2919566, 408648, 64175, '<td valign="top">Nice quick shutter getting the water or slobber.</td>', 'Nice quick shutter getting the water or slobber.', '2006-10-11 17:53:26.000000', NULL, 1),
(2919568, 409653, 64175, '<td valign="top">Great Macro.  Just a bit more lighting would help as image is a tad on the dark side.</td>', 'Great Macro.  Just a bit more lighting would help as image is a tad on the dark side.', '2006-10-11 17:53:42.000000', NULL, 1),
(2919572, 409741, 64175, '<td valign="top">Will we see this one in the Woody Challenge as well?  I like it.</td>', 'Will we see this one in the Woody Challenge as well?  I like it.', '2006-10-11 17:54:09.000000', NULL, 1),
(2919573, 407200, 64175, '<td valign="top">Wow, he''s been busier than the average bunny.</td>', 'Wow, he''s been busier than the average bunny.', '2006-10-11 17:54:25.000000', NULL, 1),
(2919575, 408922, 64175, '<td valign="top">Simplistic and nice to view.</td>', 'Simplistic and nice to view.', '2006-10-11 17:54:36.000000', NULL, 1),
(2919576, 409492, 64175, '<td valign="top">Flash setup/reflection above ducks head is a bit distracting.</td>', 'Flash setup/reflection above ducks head is a bit distracting.', '2006-10-11 17:54:40.000000', NULL, 1),
(2919583, 409832, 64175, '<td valign="top">Ha, ha, I just commented on someone else who used "abduction" that they should use the "Ab-Duck-tion".  Nice. However, the use of the 4 blue dots looks more like stars are chasing him (kind of like Close Encounters). Might have accomplished the interrogation look better by omitting those lights and just leaving the one spotlight on him or finding a single spot light look.</td>', 'Ha, ha, I just commented on someone else who used "abduction" that they should use the "Ab-Duck-tion".  Nice. However, the use of the 4 blue dots looks more like stars are chasing him (kind of like Close Encounters). Might have accomplished the interrogation look better by omitting those lights and just leaving the one spotlight on him or finding a single spot light look.', '2006-10-11 17:55:20.000000', NULL, 1),
(2919595, 408867, 64175, '<td valign="top">Just a bit closer (more of a closeup) on the duck would have made this better. Nice concept</td>', 'Just a bit closer (more of a closeup) on the duck would have made this better. Nice concept', '2006-10-11 17:57:18.000000', NULL, 1),
(2919610, 407216, 64175, '<td valign="top">Hippy Chick hanging out with the squirrels.  Nice.</td>', 'Hippy Chick hanging out with the squirrels.  Nice.', '2006-10-11 17:59:38.000000', NULL, 1),
(2919618, 407608, 64175, '<td valign="top">The ducky gets a little lost with the leg just in front of its face. I think it may have turned out better if he was slightly in front of the leg or just behind it. My eye follows the dark line of the leg to the white scarf and then must work its way back to catch the duck pilot.  Very original concept though.  6.</td>', 'The ducky gets a little lost with the leg just in front of its face. I think it may have turned out better if he was slightly in front of the leg or just behind it. My eye follows the dark line of the leg to the white scarf and then must work its way back to catch the duck pilot.  Very original concept though.  6.', '2006-10-11 18:01:36.000000', NULL, 1),
(2919624, 407479, 64175, '<td valign="top">Nice shot but a bit too much negative space on right half of photo.  At least you didn''t name the duck T.O.</td>', 'Nice shot but a bit too much negative space on right half of photo.  At least you didn''t name the duck T.O.', '2006-10-11 18:02:14.000000', NULL, 1),
(2919625, 408726, 64175, '<td valign="top">Duck is a little flat (in color) against such a bright shiny background.</td>', 'Duck is a little flat (in color) against such a bright shiny background.', '2006-10-11 18:02:16.000000', NULL, 1),
(2919634, 406734, 48339, '<td valign="top">probably #1, but at least top 3</td>', 'probably #1, but at least top 3', '2006-10-11 18:05:22.000000', NULL, 1),
(2919640, 406603, 48339, '<td valign="top">This also could go to the top, great wide perspective and clarity. 1,2,or 3</td>', 'This also could go to the top, great wide perspective and clarity. 1,2,or 3', '2006-10-11 18:06:42.000000', NULL, 1),
(2919648, 409274, 48339, '<td valign="top">a top 3 finish for you. nice expresion.</td>', 'a top 3 finish for you. nice expresion.', '2006-10-11 18:07:59.000000', NULL, 1),
