(2919722, 409808, 66341, '<td valign="top">great set, but light is very harsh</td>', 'great set, but light is very harsh', '2006-10-11 18:27:21.000000', NULL, 1),
(2919735, 407393, 66341, '<td valign="top">nice dreamlike soft haze. Nice choice of scales, and lovely close in &amp; tight composition. Niggle - looks to me like the red channel is clipped over most of ducky''s head, causing that odd interior halo. I might be wrong though.</td>', 'nice dreamlike soft haze. Nice choice of scales, and lovely close in & tight composition. Niggle - looks to me like the red channel is clipped over most of ducky''s head, causing that odd interior halo. I might be wrong though.', '2006-10-11 18:31:49.000000', NULL, 1),
(2919737, 407771, 57413, '<td valign="top">This photo is cool.  Sharp and concise.</td>', 'This photo is cool.  Sharp and concise.', '2006-10-11 18:32:11.000000', NULL, 1),
(2919740, 409524, 57413, '<td valign="top">Well done.  nice job with scenery and reflection.</td>', 'Well done.  nice job with scenery and reflection.', '2006-10-11 18:33:15.000000', NULL, 1),
(2919746, 408311, 66341, '<td valign="top">I like this a lot. Idea &amp; composition &amp; exposure are all great. Two suggestions for small improvements - 1/ there is too much dead space top &amp; bottom. I''d crop it off. 2/ you might struggle to take me seriously with this one - get direct eye-contact with the duckies, either with a lower camera position, or buy diferent ducks that are looking upwards towards the camera</td>', 'I like this a lot. Idea & composition & exposure are all great. Two suggestions for small improvements - 1/ there is too much dead space top & bottom. I''d crop it off. 2/ you might struggle to take me seriously with this one - get direct eye-contact with the duckies, either with a lower camera position, or buy diferent ducks that are looking upwards towards the camera', '2006-10-11 18:34:16.000000', NULL, 1),
(2919753, 409273, 60868, '<td valign="top">nice composition</td>', 'nice composition', '2006-10-11 18:35:26.000000', NULL, 1),
(2919756, 408602, 66341, '<td valign="top">Great lighting and composition. I''m gonna give this a high score, but for another point you''d have to change the angles a bit so that the reflection is making direct eye contact with the lens.</td>', 'Great lighting and composition. I''m gonna give this a high score, but for another point you''d have to change the angles a bit so that the reflection is making direct eye contact with the lens.', '2006-10-11 18:36:10.000000', NULL, 1),
