(2922558, 409274, 64623, '<td valign="top">Your man''s face seems too yellow to me.</td>', 'Your man''s face seems too yellow to me.', '2006-10-12 14:16:18.000000', NULL, 1),
(2922559, 409610, 64623, '<td valign="top">Looks like a tag was left on the backside of the green duck.  I think I would have taken it off so it wasn''t a distraction.</td>', 'Looks like a tag was left on the backside of the green duck.  I think I would have taken it off so it wasn''t a distraction.', '2006-10-12 14:17:19.000000', NULL, 1),
