(2922922, 409312, 44490, '<td valign="top">Nice angle, colors, and composition, just needs focus or DOF to include the ducky.</td>', 'Nice angle, colors, and composition, just needs focus or DOF to include the ducky.', '2006-10-12 15:48:40.000000', NULL, 1),
