INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2923660, 408914, 61889, '<td valign="top">I really like this one! Great idea :)</td>', 'I really like this one! Great idea :)', '2006-10-12 20:24:13.000000', NULL, 1),
(2923692, 409231, 46832, '<td valign="top">What did you do with the Ducky?  Did you kill him and hide the body?  We''re on to you...  We''re coming to get you.</td>', 'What did you do with the Ducky?  Did you kill him and hide the body?  We''re on to you...  We''re coming to get you.', '2006-10-12 20:37:57.000000', NULL, 1),
(2923846, 409762, 25355, '<td valign="top">It''s a nice clear shot, but I''m not sure what all the white points are. Doesn''t really have an impact or "cleverness" about it for this sort of Challenge. ;-)</td>', 'It''s a nice clear shot, but I''m not sure what all the white points are. Doesn''t really have an impact or "cleverness" about it for this sort of Challenge. ;-)', '2006-10-12 21:23:39.000000', NULL, 1),
(2923850, 409779, 25355, '<td valign="top">Good use of props (bubbles), but I hope you realise there''s a big difference between bubbles that rise to the surface in water and soap bubbles that float in the air. ;-)</td>', 'Good use of props (bubbles), but I hope you realise there''s a big difference between bubbles that rise to the surface in water and soap bubbles that float in the air. ;-)', '2006-10-12 21:25:48.000000', NULL, 1),
(2923860, 406603, 25355, '<td valign="top">The two shafts thrusting down gives the impression of menace to the duck, and you wonder, would he survive if cast upon the water?</td>', 'The two shafts thrusting down gives the impression of menace to the duck, and you wonder, would he survive if cast upon the water?', '2006-10-12 21:30:43.000000', NULL, 1),
(2923866, 409158, 25355, '<td valign="top">"You''re talking to me? I have a monkey"s brain for a brain." ;-)</td>', '"You''re talking to me? I have a monkey"s brain for a brain." ;-)', '2006-10-12 21:32:11.000000', NULL, 1),
(2923874, 409370, 25355, '<td valign="top">I never saw it documented that the Apollo astronauts left rubber duckies on the Moon....</td>', 'I never saw it documented that the Apollo astronauts left rubber duckies on the Moon....', '2006-10-12 21:33:59.000000', NULL, 1),
(2923880, 408225, 25355, '<td valign="top">If an infinite number of duckies ... yada-yada ..... collected works of Shakespeare and Monty Python (Volume One: Monty Python)</td>', 'If an infinite number of duckies ... yada-yada ..... collected works of Shakespeare and Monty Python (Volume One: Monty Python)', '2006-10-12 21:36:25.000000', NULL, 1),
(2923884, 407034, 2158, '<td valign="top">Interesting setup.  I think you should have got a bit closer and taken the shot from ducky''s level.</td>', 'Interesting setup.  I think you should have got a bit closer and taken the shot from ducky''s level.', '2006-10-12 21:36:48.000000', NULL, 1),
(2923885, 409587, 25355, '<td valign="top">The round sunglasses are wonderful; or at least made me snigger. ;-)</td>', 'The round sunglasses are wonderful; or at least made me snigger. ;-)', '2006-10-12 21:37:07.000000', NULL, 1),
(2923889, 409704, 25355, '<td valign="top">Diofficult exposure having the black dog there too - highlights on the ducks are blown out detrimentally.</td>', 'Diofficult exposure having the black dog there too - highlights on the ducks are blown out detrimentally.', '2006-10-12 21:38:17.000000', NULL, 1),
(2923906, 409361, 25355, '<td valign="top">Oh, if it''s not a shotgun wedding, maybe he''ll get pistol-whipped. ;-)<br/>I really think the angel duck should be yellow (was it desaturated?) - it would certainly make the ducks easier to find.</td>', 'Oh, if it''s not a shotgun wedding, maybe he''ll get pistol-whipped. ;-)I really think the angel duck should be yellow (was it desaturated?) - it would certainly make the ducks easier to find.', '2006-10-12 21:45:34.000000', NULL, 1),
(2923910, 409561, 25355, '<td valign="top">I can''t see what the block of wood is for, it doesn''t add anything to the image that''s worthwhile. ;-)</td>', 'I can''t see what the block of wood is for, it doesn''t add anything to the image that''s worthwhile. ;-)', '2006-10-12 21:47:23.000000', NULL, 1),
(2923921, 409280, 25355, '<td valign="top">Man, it must be fun in the brainstorming sessions at the Rubber Ducky manufacturing plant.</td>', 'Man, it must be fun in the brainstorming sessions at the Rubber Ducky manufacturing plant.', '2006-10-12 21:49:30.000000', NULL, 1),
(2923936, 407937, 25355, '<td valign="top">Basic Techniques of Photography, Book 1? No wonder most of us still have photographic troubles, if the basic Techniques fill more than one book...<br/> <br/>Not only that, when I first read the second bottom title, I read it as "Would the Buddha be a Milkman?"<br/> <br/>Oh,@yeah, nice photo. ;-)</td>', 'Basic Techniques of Photography, Book 1? No wonder most of us still have photographic troubles, if the basic Techniques fill more than one book... Not only that, when I first read the second bottom title, I read it as "Would the Buddha be a Milkman?" Oh,@yeah, nice photo. ;-)', '2006-10-12 21:55:16.000000', NULL, 1),
(2923988, 407647, 66733, '<td valign="top">great shot !</td>', 'great shot !', '2006-10-12 22:14:24.000000', NULL, 1),
