(2924119, 407308, 15358, '<td valign="top">after looking at 50 ducky images, I really like this one.</td>', 'after looking at 50 ducky images, I really like this one.', '2006-10-12 22:50:13.000000', NULL, 1),
(2924123, 407216, 66733, '<td valign="top">really great shot !</td>', 'really great shot !', '2006-10-12 22:51:25.000000', NULL, 1),
