(2926157, 409843, 66654, '<td valign="top">I think should be the next movie starring the duckys. I like it.</td>', 'I think should be the next movie starring the duckys. I like it.', '2006-10-13 15:31:27.000000', NULL, 1),
(2926178, 409653, 66654, '<td valign="top">It is cute.10</td>', 'It is cute.10', '2006-10-13 15:35:20.000000', NULL, 1),
(2926183, 409823, 64175, '<td valign="top">I love Wood Ducks too, and this is a great shot of the male.  The rubber ducky is so hidden in the shadow of the tail, it is almost non-existent. But it does meet the challenge.</td>', 'I love Wood Ducks too, and this is a great shot of the male.  The rubber ducky is so hidden in the shadow of the tail, it is almost non-existent. But it does meet the challenge.', '2006-10-13 15:36:52.000000', NULL, 1),
