(2928686, 407864, 60477, '<td valign="top">You might have patched the white flares on the duck. Somewhat weal on focus. On the plus side this looks like futuristic "bad" water. 5</td>', 'You might have patched the white flares on the duck. Somewhat weal on focus. On the plus side this looks like futuristic "bad" water. 5', '2006-10-14 18:16:36.000000', NULL, 1),
(2928689, 406737, 60477, '<td valign="top">Ambitious and effective. A couple of points off for focus and depth of field. Still a solid 7 imho.</td>', 'Ambitious and effective. A couple of points off for focus and depth of field. Still a solid 7 imho.', '2006-10-14 18:17:55.000000', NULL, 1),
(2928693, 408830, 60477, '<td valign="top">Too much brightness and lack of focus on the duck hurts your excellent idea.</td>', 'Too much brightness and lack of focus on the duck hurts your excellent idea.', '2006-10-14 18:18:59.000000', NULL, 1),
(2928695, 408481, 60477, '<td valign="top">I''d love to hear the story behind this shot...sorry to say the focus...which might have been hard to get...hurts the shot a great deal. At first glance I missed the real star of the shot.</td>', 'I''d love to hear the story behind this shot...sorry to say the focus...which might have been hard to get...hurts the shot a great deal. At first glance I missed the real star of the shot.', '2006-10-14 18:21:30.000000', NULL, 1),
(2928698, 409158, 60477, '<td valign="top">Funny stuff. Nice focus. A couple of flash marks could have been easily fixed--but still a fine photo.</td>', 'Funny stuff. Nice focus. A couple of flash marks could have been easily fixed--but still a fine photo.', '2006-10-14 18:23:03.000000', NULL, 1),
(2928700, 409213, 60477, '<td valign="top">Nice use of spot focusing,</td>', 'Nice use of spot focusing,', '2006-10-14 18:24:02.000000', NULL, 1),
(2928702, 408176, 60477, '<td valign="top">Excellent! Great technical execution of a fine idea.</td>', 'Excellent! Great technical execution of a fine idea.', '2006-10-14 18:24:53.000000', NULL, 1),
