(2928756, 408225, 60477, '<td valign="top">Where have I seen that typerwriter before? A great concept here, but the focus could be better.</td>', 'Where have I seen that typerwriter before? A great concept here, but the focus could be better.', '2006-10-14 18:50:09.000000', NULL, 1),
(2928758, 409660, 60477, '<td valign="top">I think they might leave the light on for you in the ribbon room.</td>', 'I think they might leave the light on for you in the ribbon room.', '2006-10-14 18:50:50.000000', NULL, 1),
