(2928794, 409370, 60477, '<td valign="top">I bet there''s a rubber duck on the far side of the excellent shot of the moon!</td>', 'I bet there''s a rubber duck on the far side of the excellent shot of the moon!', '2006-10-14 19:08:51.000000', NULL, 1),
(2928798, 409777, 60477, '<td valign="top">WOW...well done!</td>', 'WOW...well done!', '2006-10-14 19:10:17.000000', NULL, 1),
(2928800, 406238, 60477, '<td valign="top">Have to take some points of for using real instead of rubber ducks,,,great shot for a different challenge. 4</td>', 'Have to take some points of for using real instead of rubber ducks,,,great shot for a different challenge. 4', '2006-10-14 19:10:55.000000', NULL, 1),
